/// <summary>
/// The controller class for Planner code clean up batch job.
/// </summary>
class METPlannerCodeCleanupController extends SysOperationServiceController
{
}

Method.Source:
    /// <summary>
    /// The new method of the class.
    /// </summary>
    protected void new()
    {
        super();

        this.parmClassName(classStr(METPlannerCodeCleanupService));
        this.parmMethodName(methodStr(METPlannerCodeCleanupService, processOperation));        
    }

/// <summary>
/// The caption method of the batch job dialog.
/// </summary>
/// <returns>String value to be used on dialog</returns>
public ClassDescription caption()
{
    return "@MET:METPlannerCodeCleanUpBatchJob";
}

/// <summary>
/// The main method of the batch job.
/// </summary>
/// <param name = "_args">The arguments passed by the caller object.</param>
public static void main(Args _args)
{
    SysOperationController controller = new METPlannerCodeCleanupController();
    controller.startOperation();
}
